package ru.neverland.townypolicies.gui;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.inventory.*;
import org.bukkit.inventory.*;
import java.util.*;
import ru.neverland.townypolicies.service.*;
import static ru.neverland.townypolicies.service.Ui.*;
public final class PoliciesMenu implements Listener {
    private final org.bukkit.plugin.Plugin plugin;private final PoliciesService service;
    private static final class View implements InventoryHolder{final UUID town;final Map<Integer,Runnable> actions=new HashMap<>();Inventory inventory;View(UUID town){this.town=town;}public Inventory getInventory(){ try (var suiteGuard1 = ru.neverland.core.SuiteState.guard()) {return inventory;} }}
    public PoliciesMenu(org.bukkit.plugin.Plugin plugin,PoliciesService service){this.plugin=plugin;this.service=service;}
    private boolean access(Player p,UUID town){var own=service.town(p);return p.hasPermission("neverlandtownypolicies.admin")||p.hasPermission("neverlandtownypolicies.use")&&own!=null&&own.getUUID().equals(town);}
    public void open(Player p,UUID town,String group,String mode){ try (var suiteGuard2 = ru.neverland.core.SuiteState.guard()) {if(!access(p,town)){tell(p,"Нет доступа к этому городу.");return;}var view=service.policies(town).orElse(null);if(view==null){tell(p,"Ожидаются данные города.");return;}var settings=service.settings();var v=new View(town);v.inventory=ru.neverland.core.MenuStyle.inventory(plugin, v,54,color("&6Городские политики"));var state=view.state();
        if(group==null){int slot=10;for(var g:settings.groups().values()){var selected=g.options().get(state.mode(g));button(v,slot++,icon(g.icon()),"&e"+g.name(),List.of("Режим: "+(selected==null?"Отсутствует в настройках":selected.name()),view.status().get(g.id()),"Смена через: "+waitTime(state.next(g.id())),"Нажмите: сравнить режимы."),()->open(p,town,g.id(),null));}button(v,30,Material.COMPASS,"&eРазвитие, оборона и восстановление",List.of("Сравнить наборы политик и их последствия."),()->open(p,town,"presets",null));button(v,31,Material.WRITABLE_BOOK,"&eИстория указов",List.of("Последние 30 изменений."),()->open(p,town,"history",null));}
        else if(group.equals("presets")){presets(p,v);}
        else if(group.startsWith("preset/")){preset(p,v,group.substring(7),"admin".equals(mode));}
        else if(group.equals("history")){int slot=0;var changes=new ArrayList<>(state.history());Collections.reverse(changes);for(var h:changes){var g=settings.groups().get(h.group());var before=g.options().get(h.before());var after=g.options().get(h.after());button(v,slot++,Material.PAPER,"&e"+g.name(),List.of((before==null?"Прежний режим":before.name())+" → "+(after==null?"Удалённый режим":after.name()),"Автор: "+h.actorName(),java.time.format.DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm").withZone(java.time.ZoneId.of("Europe/Moscow")).format(java.time.Instant.ofEpochMilli(h.at()))),null);}}
        else{var g=settings.groups().get(group);if(g==null){tell(p,"Политика не найдена.");return;}if(mode==null){int optionIndex=0;int[] optionSlots={19,22,25,28,31,34};for(var option:g.options().values()){button(v,optionSlots[optionIndex++],icon(option.icon()),"&e"+option.name(),lore(town,g,option,state.mode(g).equals(option.id())),()->open(p,town,group,option.id()));}}
            else{var option=g.options().get(mode);if(option==null){tell(p,"Режим не найден.");return;}button(v,13,icon(option.icon()),"&e"+option.name(),lore(town,g,option,state.mode(g).equals(mode)),null);if(!state.mode(g).equals(mode))button(v,31,Material.LIME_DYE,"&aПодтвердить указ",List.of("Изменится только политика: "+g.name(),"Смена бесплатна; издержки режима действуют постоянно.","Следующая смена этой политики через "+settings.cooldownMillis()/3600000+" ч.","Текущее ожидание: "+waitTime(state.next(group))),()->{try{acknowledge(p,v,service.choose(p,town,group,mode,state.revision(),settings,false),"Указ принят: "+g.name()+" — "+option.name(),group);}catch(Exception e){tell(p,"&c"+e.getMessage());}});button(v,40,Material.COMPARATOR,"&eСравнить режимы",List.of(),()->open(p,town,group,null));}}
        if(group!=null)button(v,45,Material.ARROW,group.startsWith("preset/")?"&aК наборам":"&aВсе политики",List.of(),()->open(p,town,group.startsWith("preset/")?"presets":null,null));if(Bukkit.getPluginManager().isPluginEnabled("NeverLandTownyGovernance"))button(v,48,Material.BOOK,"&eЗаконы и совет",List.of("Открыть существующее управление городом."),()->p.performCommand("town governance"));button(v,49,Material.SPYGLASS,"&aОбновить",List.of(),()->open(p,town,group,mode));if(Bukkit.getPluginManager().isPluginEnabled("NeverLandTownyResources"))button(v,53,Material.CHEST,"&eГородские ресурсы",List.of(),()->p.performCommand("town resources"));p.openInventory(v.inventory);
    } }
    private void acknowledge(Player p,View expected,java.util.concurrent.CompletionStage<UUID> receipt,String success,String group){receipt.whenComplete((town,error)->ru.neverland.core.SuiteScheduler.entity(plugin,p,()->{if(!p.isOnline())return;if(error!=null){tell(p,"&cИзменение не подтверждено. Сохранённые режимы доступны в истории.");return;}tell(p,success);if(p.getOpenInventory().getTopInventory().getHolder()==expected&&access(p,town))open(p,town,group,null);}));}
    private void presets(Player p,View v){var settings=service.presets().settings();if(!settings.enabled()){button(v,13,Material.BARRIER,"&eНаборы сейчас недоступны",List.of("Обычные политики доступны в основном меню."),null);return;}int slot=0;for(var preset:settings.presets().values()){var plan=service.presets().preview(v.town,preset.id());var lines=new ArrayList<String>();lines.add(preset.description());lines.addAll(plan.blockers());lines.addAll(plan.warnings());lines.add("Нажмите: сравнить режимы и подтвердить весь набор.");button(v,slot++,icon(preset.icon()),"&e"+preset.name(),lines,()->open(p,v.town,"preset/"+preset.id(),null));}}
    private void preset(Player p,View v,String id,boolean admin){var helper=service.presets();var preset=helper.find(id);var settings=service.settings();var catalog=helper.settings();var plan=helper.plan(v.town,id,p.getUniqueId(),p.getName(),admin);button(v,13,icon(preset.icon()),"&e"+preset.name(),List.of(preset.description(),"Каждая политика проверяется перед общим сохранением."),null);
        int slot=19;for(var e:new java.util.TreeMap<>(preset.modes()).entrySet()){var g=settings.groups().get(e.getKey());var before=g.options().get(plan.before().mode(g));var after=g.options().get(e.getValue());var lines=new ArrayList<String>();lines.add((before==null?"Прежний режим":before.name())+" → "+after.name());for(String good:after.advantages())lines.add("&a+ "+good);for(String bad:after.disadvantages())lines.add("&c− "+bad);button(v,slot++,icon(g.icon()),"&e"+g.name(),lines,null);}
        var examples=List.of(Map.entry("agrarian_complex","Аграрный комплекс"),Map.entry("foundry","Литейная"),Map.entry("army","Штаб армии"),Map.entry("baths","Городские бани"),Map.entry("research","Исследовательский институт"));slot=36;for(var example:examples){var impact=helper.impact(v.town,id,example.getKey());button(v,slot++,Material.PAPER,"&e"+example.getValue(),List.of("Влияние политик: 100% — обычный режим.","Выпуск: "+percent(impact.get("beforeProduction"))+" → "+percent(impact.get("afterProduction")),"Содержание: "+percent(impact.get("beforeUpkeep"))+" → "+percent(impact.get("afterUpkeep"))),null);}
        var notes=new ArrayList<String>(plan.blockers());notes.addAll(plan.warnings());if(service.saving())notes.add("Предыдущий указ ещё сохраняется");boolean authority=admin?p.hasPermission("neverlandtownypolicies.admin"):service.manager(p,service.town(p))&&service.town(p).getUUID().equals(v.town);if(!authority)notes.add("Подтверждает мэр или уполномоченный этого города");if(notes.isEmpty())notes.add("Условия проверены. Набор готов к подтверждению.");button(v,30,notes.isEmpty()?Material.PAPER:Material.WRITABLE_BOOK,"&eУсловия выбора",notes,null);
        boolean ready=plan.ready()&&!service.saving()&&authority;var confirmation=new ArrayList<String>(List.of("Принятие набора бесплатно.","Будут выбраны все перечисленные режимы.","Доплаты действуют при последующих расчётах содержания.","Следующая смена каждой изменённой политики через "+settings.cooldownMillis()/3600000+" ч."));if(admin)confirmation.add("Администратор обходит текущее ожидание смены.");button(v,31,ready?Material.LIME_DYE:Material.BARRIER,ready?"&aПодтвердить весь набор":"&eВыбор пока недоступен",confirmation,ready?()->{try{acknowledge(p,v,helper.choose(p,v.town,id,plan.before().revision(),settings,catalog,admin),"Набор политик сохранён.","presets");}catch(Exception error){tell(p,"&c"+error.getMessage());}}:null);
    }
    private static String percent(Object raw){return java.math.BigDecimal.valueOf(((Number)raw).doubleValue()*100).setScale(2,java.math.RoundingMode.HALF_UP).stripTrailingZeros().toPlainString()+"%";}
    private List<String> lore(UUID town,ru.neverland.townypolicies.model.PolicyGroup g,ru.neverland.townypolicies.model.PolicyOption p,boolean selected){var lines=new ArrayList<String>();for(String text:p.advantages())lines.add("&a+ "+text);for(String text:p.disadvantages())lines.add("&c− "+text);if(!p.effects().isEmpty()){lines.add("Фактические эффекты:");p.effects().forEach((key,value)->lines.add(EffectLabels.value(key,value)));}String reason=service.unavailable(town,g,p);if(!reason.isEmpty())lines.add("&eПриостановлено: "+reason);if(selected)lines.add("&aВыбранный режим");return lines;}
    private String waitTime(long until){long seconds=Math.max(0,(until-System.currentTimeMillis()+999)/1000);return seconds==0?"доступна сейчас":seconds/3600+" ч. "+seconds%3600/60+" мин. "+seconds%60+" сек.";}
    private void button(View v,int slot,Material material,String name,List<String> lines,Runnable action){var item=new ItemStack(material);var meta=item.getItemMeta();meta.setDisplayName(ru.neverland.core.MenuStyle.nameLegacy(color(name)));meta.setLore(ru.neverland.core.MenuStyle.loreStrings(lines.stream().map(x->color("&7"+x)).toList()));meta.addItemFlags(ItemFlag.HIDE_ATTRIBUTES);item.setItemMeta(meta);v.inventory.setItem(slot,item);if(action!=null)v.actions.put(slot,action);}
    @EventHandler public void click(InventoryClickEvent e){ try (var suiteGuard3 = ru.neverland.core.SuiteState.guard()) {if(ru.neverland.core.SuiteState.frozen("NeverLandTownyPolicies")){ru.neverland.core.ModuleGate.stopEvent(e);return;}if(!(e.getView().getTopInventory().getHolder() instanceof View v))return;e.setCancelled(true);if(!(e.getWhoClicked() instanceof Player p))return;if(!access(p,v.town)){p.closeInventory();return;}var action=v.actions.get(e.getRawSlot());if(action!=null)ru.neverland.core.SuiteScheduler.entity(plugin, p,()->{if(p.isOnline()&&p.getOpenInventory().getTopInventory().getHolder()==v&&access(p,v.town))action.run();});} }
    @EventHandler public void drag(InventoryDragEvent e){ try (var suiteGuard4 = ru.neverland.core.SuiteState.guard()) {if(ru.neverland.core.SuiteState.frozen("NeverLandTownyPolicies")){ru.neverland.core.ModuleGate.stopEvent(e);return;}if(e.getView().getTopInventory().getHolder() instanceof View)e.setCancelled(true);} }
}
